class Solution {
public:
    bool checkZeroOnes(string s) {
        int max1 = 0, max0 = 0, run = 1;
        for (int i = 1; i <= (int)s.size(); i++) {
            if (i < (int)s.size() && s[i] == s[i - 1]) {
                run++;
            } else {
                if (s[i - 1] == '1')
                    max1 = max(max1, run);
                else
                    max0 = max(max0, run);
                run = 1;
            }
        }
        return max1 > max0;
    }
};
